#!/usr/bin/env node
/**
 * Generate src/components/icons.generated.ts from @untitledui/icons.
 *
 * The package is a web React library (it renders DOM <svg>), so the app draws
 * the same shapes with react-native-svg instead. Each icon component is called
 * with real React and its element tree read back, so nothing parses source.
 *
 * Licence (read from the package's LICENSE file, not package.json, which says
 * MIT): use in personal and commercial projects is allowed; distributing the
 * icons, in original or modified form, is not. So the generated file is
 * gitignored and rebuilt from node_modules; the shapes ship only inside the
 * app binary. Shipping them inside the app was confirmed against
 * untitledui.com/license by John, 10 Oct 2026.
 */

import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const here = path.dirname(fileURLToPath(import.meta.url));
const out = path.resolve(here, "..", "src", "components", "icons.generated.ts");

/** App name → Untitled UI component. */
const ICONS = {
  back: "ChevronLeft",
  forward: "ChevronRight",
  down: "ChevronDown",
  up: "ChevronUp",
  close: "XClose",
  more: "DotsHorizontal",
  check: "Check",
  note: "MessageTextSquare02",
  bookmark: "Bookmark",
  compare: "Columns02",
  copy: "Copy01",
  share: "Share01",
  search: "SearchSm",
  download: "Download01",
};

function walk(node, shapes) {
  if (node === null || typeof node !== "object") return;
  const { type, props } = node;
  if (typeof type === "string" && type !== "svg") {
    const attrs = {};
    for (const [k, v] of Object.entries(props)) if (k !== "children") attrs[k] = v;
    shapes.push({ tag: type, attrs });
  }
  const children = props?.children;
  for (const child of Array.isArray(children) ? children : [children]) walk(child, shapes);
}

const result = {};
for (const [name, component] of Object.entries(ICONS)) {
  const mod = require(`@untitledui/icons/${component}`);
  const Icon = mod[component] ?? mod.default;
  const shapes = [];
  walk(Icon({}), shapes);
  if (shapes.length === 0) throw new Error(`${component}: no shapes`);
  result[name] = shapes;
}

writeFileSync(
  out,
  `// Generated by scripts/sync-icons.mjs from @untitledui/icons. Do not edit; not committed (licence).\n\n` +
    `export const ICON_SHAPES = ${JSON.stringify(result, null, 2)} as const;\n\n` +
    `export type IconName = keyof typeof ICON_SHAPES;\n`,
);
console.log(`icons: ${Object.keys(result).length} → ${path.relative(process.cwd(), out)}`);
